-- Biology Units 7-10 hierarchy, GCE A/L 2017 (NIE)
-- Official source: National Institute of Education Biology syllabus implemented from 2017.

with v as(select id from public.syllabus_versions where code='GCE_AL_2017'),b as(select id from public.subjects where name='Biology'),x(code,title,position) as(values ('7.1.0','Investigates the molecular basis of genetic materials',1),('7.2.0','Gets updated on gene technology',2),('8.1.0','Engages in biological analysis of relationships between organisms and their environment',1),('8.2.0','Explores the heterogeneous nature of the biotic environment',2),('8.3.0','Explores biodiversity as a component of the environment',3),('8.4.0','Explores methods of biodiversity and environmental conservation',4),('9.1.0','Investigates diversity and handling of microorganisms',1),('9.2.0','Investigates microorganisms as human pathogens',2),('9.3.0','Investigates microbial use in industry, agriculture and environment',3),('9.4.0','Utilizes microbiological concepts to maintain water quality',4),('9.5.0','Explores the impact of microbes on food',5),('10.1.0','Uses biological concepts to promote living standards',1)) insert into public.syllabus_competencies(syllabus_version_id,subject_id,code,title,description,position) select v.id,b.id,x.code,x.title,'NIE GCE A/L Biology 2017 competency.',x.position from v cross join b cross join x where not exists(select 1 from public.syllabus_competencies z where z.syllabus_version_id=v.id and z.subject_id=b.id and z.code=x.code);
with v as(select id from public.syllabus_versions where code='GCE_AL_2017'),b as(select id from public.subjects where name='Biology'),x(code,cc,title,description,position,unit) as(values ('7.1.1','7.1.0','Examines the structures and functions of genetic materials','DNA/RNA, chromosomes, DNA replication and repair.','1','7'),('7.1.2','7.1.0','Examines genes and how they work','Genes, genetic code, protein synthesis and gene expression.','2','7'),('7.1.3','7.1.0','Examines the molecular basis of mutations','Mutations, mutagens, disorders, counselling and evolution.','3','7'),('7.2.1','7.2.0','Gets updated on tools, techniques and methods of gene technology','DNA isolation, enzymes, electrophoresis, probes, cloning, vectors and gene transfer.','1','7'),('7.2.2','7.2.0','Gets updated on DNA analysis','Restriction maps, sequencing, DNA fingerprints and PCR.','2','7'),('7.2.3','7.2.0','Updates on the applications of gene technology','GM organisms, applications, biosafety and socio-economic concerns.','3','7'),('8.1.1','8.1.0','Investigates components of an ecosystem','Biotic/abiotic components and environmental organization.','1','8'),('8.1.2','8.1.0','Investigates major processes of an ecosystem','Habitat, niche, food webs, interactions, material and energy flow.','2','8'),('8.2.1','8.2.0','Investigates main biomes of the world','Major terrestrial biomes, distribution and characteristics.','1','8'),('8.2.2','8.2.0','Investigates ecosystems of Sri Lanka','Sri Lankan forests, grasslands, wetlands and coastal ecosystems.','2','8'),('8.3.1','8.3.0','Explores biodiversity and threats due to human actions','Biodiversity, hotspots, threats, extinction and species categories.','1','8'),('8.3.2','8.3.0','Gets updated on global environmental problems','Global warming, climate change, ozone depletion, desertification and acid rain.','2','8'),('8.4.1','8.4.0','Investigates how biodiversity and environment can be conserved at global and national level','In-situ/ex-situ conservation, agreements and Sri Lankan legislation.','1','8'),('9.1.1','9.1.0','Explores the diversity and nature of microorganisms','Bacteria, archaea, cyanobacteria, protists, fungi, viruses, viroids and prions.','1','9'),('9.1.2','9.1.0','Explores some basic laboratory techniques in microbiology','Sterilization, culture media, inoculation, staining and handling.','2','9'),('9.2.1','9.2.0','Explores the concepts and principles relevant to infectious diseases','Normal microbiota, pathogens, virulence, toxins, entry portals and diseases.','1','9'),('9.2.2','9.2.0','Explores the methods of controlling microbial population','Disinfectants, antiseptics, immunization, antibiotics and chemotherapy.','2','9'),('9.3.1','9.3.0','Investigates and explores the use of microorganisms in industry, agriculture and environment','Industrial products, bioremediation, waste treatment, biofertilizers and biocontrol.','1','9'),('9.3.2','9.3.0','Uses the functions of soil microorganisms to maintain soil health','Soil microbes, mineral cycles, rhizosphere and plant growth.','2','9'),('9.4.1','9.4.0','Uses microbiological concepts and principles in potable water and waste water management','Water contamination, indicators, water treatment and wastewater.','1','9'),('9.5.1','9.5.0','Contributes to the prevention of diseases caused by spoiled food','Food spoilage, foodborne infection/intoxication and preservation.','1','9'),('10.1.1','10.1.0','Investigates ornamental fish culture systems','Aquaculture, aquarium maintenance, diseases and environmental impacts.','1','10'),('10.1.2','10.1.0','Investigates opportunities related to horticultural practices','Nursery management, protected agriculture, tissue culture and floriculture.','2','10'),('10.1.3','10.1.0','Uses biological knowledge to minimize damage caused by vector-borne diseases','Dengue and filariasis vectors, breeding sites and control.','3','10'),('10.1.4','10.1.0','Utilizes knowledge on food preservation and postharvest losses','Preservation principles and reducing postharvest losses.','4','10'),('10.1.5','10.1.0','Gets updated in applications of emerging technologies related to biology','Nanobiology, stem cells and Human Genome Project.','5','10')) insert into public.syllabus_competency_levels(competency_id,syllabus_version_id,subject_id,code,title,description,position) select c.id,v.id,b.id,x.code,x.title,x.description,x.position from v cross join b cross join x join public.syllabus_competencies c on c.syllabus_version_id=v.id and c.subject_id=b.id and c.code=x.cc where not exists(select 1 from public.syllabus_competency_levels z where z.syllabus_version_id=v.id and z.subject_id=b.id and z.code=x.code);
with v as(select id from public.syllabus_versions where code='GCE_AL_2017'),b as(select id from public.subjects where name='Biology'),cl as(select * from public.syllabus_competency_levels where syllabus_version_id=(select id from v) and subject_id=(select id from b) and code like any(array['7.%','8.%','9.%','10.%'])) insert into public.syllabus_topics(unit_id,title,position) select u.id,cl.code||' — '||cl.title,100+cl.position from cl join public.syllabus_units u on u.syllabus_version_id=cl.syllabus_version_id and u.subject_id=cl.subject_id and u.position=split_part(cl.code,'.',1)::int where not exists(select 1 from public.syllabus_topics t where t.unit_id=u.id and t.title=cl.code||' — '||cl.title);
with v as(select id from public.syllabus_versions where code='GCE_AL_2017'),b as(select id from public.subjects where name='Biology'),cl as(select * from public.syllabus_competency_levels where syllabus_version_id=(select id from v) and subject_id=(select id from b) and code like any(array['7.%','8.%','9.%','10.%'])) insert into public.syllabus_subtopics(topic_id,title,description,position) select t.id,'Core learning outcomes','NIE GCE A/L Biology 2017 competency-level learning area.',1 from cl join public.syllabus_topics t on t.title=cl.code||' — '||cl.title where not exists(select 1 from public.syllabus_subtopics s where s.topic_id=t.id and s.title='Core learning outcomes');
with v as(select id from public.syllabus_versions where code='GCE_AL_2017'),b as(select id from public.subjects where name='Biology'),cl as(select * from public.syllabus_competency_levels where syllabus_version_id=(select id from v) and subject_id=(select id from b) and code like any(array['7.%','8.%','9.%','10.%'])) insert into public.syllabus_learning_outcomes(subtopic_id,competency_id,competency_level_id,code,statement,position) select s.id,cl.competency_id,cl.id,cl.code,cl.description,1 from cl join public.syllabus_topics t on t.title=cl.code||' — '||cl.title join public.syllabus_subtopics s on s.topic_id=t.id and s.title='Core learning outcomes' where not exists(select 1 from public.syllabus_learning_outcomes lo where lo.subtopic_id=s.id and lo.code=cl.code);